  if A<=s1 and e1<=B and A<=s2 and e2<=B:
   print(s1,e1,s2,e2,'count',p[9],'donut',p[12],'q',p[16], 'cstart1',p[6],'cstart2',p[7])
print('\\nH1 unique vs HFF exact/overlap in region')
